    def filter(
        self,
        *,
        project: str | None = None,
    ) -> PublicIpCollection:
        """The same collection, narrowed to the items matching these criteria."""
        return self._narrowed(project=project)

    async def _items(self) -> AsyncIterator[PublicCloudPublicIpPublicIPSummary]:
        async for data in self._session.api(
            _PublicCloudV2API
        ).list_project_public_ip_iter(
            project_id=_scoped(
                {**self._scope, **self._criteria},
                "project",
                self._session.client.settings.default_project,
            ),
            **{k: v for k, v in self._criteria.items() if k not in {"project"}},
        ):
            yield data


