    async def ssl_gateways_eligibility(
        self,
        *,
        domain: str,
    ) -> SslGatewayEligibilityStatus:
        """
        GET /1.0/sslGateway/eligibility

        Check domain eligibility

        API status: BETA.
        """
        return await self._session.api(_SslGatewayV1API).get_eligibility(domain=domain)

    async def vac_event(
        self,
        *,
        after: Instant | Date | None = None,
        before: Instant | Date | None = None,
        ongoing_only: bool | None = None,
        region: NetworkDefenseRegionEnum | None = None,
        subnets: list[str] | None = None,
    ) -> NetworkDefenseVacEventsResponse:
        """
        GET /v2/networkDefense/vac/event

        List VAC detection events
        """
        return await self._session.api(_NetworkDefenseV2API).get_vac_event(
            after=after,
            before=before,
            ongoing_only=ongoing_only,
            region=region,
            subnets=subnets,
        )

    async def vac_traffic(
        self,
        *,
        after: Instant | Date,
        subnet: str,
        before: Instant | Date | None = None,
    ) -> NetworkDefenseVacTrafficResponse:
        """
        GET /v2/networkDefense/vac/traffic

        Get VAC traffic statistics
        """
        return await self._session.api(_NetworkDefenseV2API).get_vac_traffic(
            after=after, before=before, subnet=subnet
        )
